export type TabId = number;

/**  A persistent, ordered relationship; only the selected pair owns viewports. */
export type TabPair = {
	tabs: [TabId, TabId],
	ratio: number,
};

/**
 *  Whether a tab currently holds a webview, and whether it is running.
 * 
 *  A discarded tab is not a paused page: its webview is gone and reactivating
 *  reloads the URL, then restores [`Tab::scroll`]. A frozen tab is: it keeps
 *  its page and resumes without a reload.
 */
export type TabPresence = 
/**  Bound to a pool slot and backed by a live webview. */
{ status: "live"; slot: SlotId } | 
/**  Bound to a pool slot, with its page paused in the background. */
{ status: "frozen"; slot: SlotId } | 
/**  No webview. Reactivating reloads the page. */
{ status: "discarded" } | 
/**  Rendered by the chrome itself; never consumes a slot. */
{ status: "internal" } | 
/**
 *  Its page's process exited. No webview, and none is given until the
 *  user reloads or navigates it, so a page that crashes as it loads does
 *  not crash again and again.
 */
{ status: "crashed"; cause: CrashCause };

/**
 *  A process no slot accounts for: the browser, GPU and utility processes, and
 *  the interface's own renderer.
 */
export type UnattributedProcess = {
	pid: number,
	kind: ProcessKind,
	bytes: number,
};

/**  Where content webviews sit inside the window, in logical pixels. */
